def cube(x: int) -> int:
    return x * x * x

def foo(n: int) -> int:
    ans = 0
    k = 2
    while True:
        c = cube(k)
        if c > n:
            break
        ans += n // c
        k += 1
    return ans

def bin_search(f, lo: int, up: int) -> int:
    # Find smallest x in [lo, up] such that f(x) is True.
    # Assumes f is monotonic (False...False True...True)
    up += 1  # Make upper bound exclusive
    while lo < up:
        mid = (lo + up) // 2
        if not f(mid):
            lo = mid + 1
        else:
            up = mid
    return lo

